import React, { Component } from "react";
import counterpart from "counterpart";
import { serializeQuizProperties } from "../lib/psv";
import "./Forms.css";

class QuizProps extends Component {
  state = {
    quizName: "My Quiz",
    quizQuestionFontsize: "40",
    quizAnswerFontsize: "35",
    quizQuestionCode: "en-US",
    quizAnswerCode: "ru-RU",
    error: "",
  };

  addProperties = () => {
    try {
      const serialized = serializeQuizProperties({
        name: this.state.quizName,
        questionLanguage: this.state.quizQuestionCode,
        answerLanguage: this.state.quizAnswerCode,
        questionFontSize: this.state.quizQuestionFontsize,
        answerFontSize: this.state.quizAnswerFontsize,
      });
      this.props.buttonClicked(serialized);
      this.setState({ error: "" });
    } catch (error) {
      this.setState({ error: error.message });
    }
  };

  render() {
    return (
      <div className="settings-content">
        <div className="settings-grid">
          <label className="field field-wide">
            <span>{counterpart.translate("quizName")}</span>
            <input type="text" value={this.state.quizName}
              onChange={(event) => this.setState({ quizName: event.target.value })} />
          </label>
          <label className="field">
            <span>{counterpart.translate("quizQuestionCode")}</span>
            <input type="text" value={this.state.quizQuestionCode}
              onChange={(event) => this.setState({ quizQuestionCode: event.target.value })} />
          </label>
          <label className="field">
            <span>{counterpart.translate("quizAnswerCode")}</span>
            <input type="text" value={this.state.quizAnswerCode}
              onChange={(event) => this.setState({ quizAnswerCode: event.target.value })} />
          </label>
          <label className="field">
            <span>{counterpart.translate("quizQuestionFontsize")}</span>
            <input type="number" min="8" value={this.state.quizQuestionFontsize}
              onChange={(event) => this.setState({ quizQuestionFontsize: event.target.value })} />
          </label>
          <label className="field">
            <span>{counterpart.translate("quizAnswerFontsize")}</span>
            <input type="number" min="8" value={this.state.quizAnswerFontsize}
              onChange={(event) => this.setState({ quizAnswerFontsize: event.target.value })} />
          </label>
        </div>
        {this.state.error && <p className="form-error" role="alert">{this.state.error}</p>}
        <div className="settings-footer">
          <a href="langcodes.html" target="_blank" rel="noopener noreferrer">
            {counterpart.translate("languageCodeLookup")}
          </a>
          <button className="button button-primary" onClick={this.addProperties}
            disabled={this.props.disabled}>
            {this.props.disabled
              ? counterpart.translate("propertiesAdded")
              : counterpart.translate("addProperties")}
          </button>
        </div>
      </div>
    );
  }
}

export default QuizProps;



