/**
 * Small dependency-free JSON storage adapter.
 *
 * Pass any Web Storage-compatible object (localStorage, sessionStorage, or a
 * test implementation). The optional namespace prevents key collisions.
 */
export function createJsonStorage(storage, namespace = "app") {
  if (!storage || typeof storage.getItem !== "function") {
    throw new TypeError("A Web Storage-compatible object is required");
  }

  const storageKey = (key) => `${namespace}:${key}`;

  return {
    get(key, fallback = null) {
      try {
        const value = storage.getItem(storageKey(key));
        return value === null ? fallback : JSON.parse(value);
      } catch (error) {
        return fallback;
      }
    },

    set(key, value) {
      try {
        storage.setItem(storageKey(key), JSON.stringify(value));
        return true;
      } catch (error) {
        return false;
      }
    },

    remove(key) {
      try {
        storage.removeItem(storageKey(key));
        return true;
      } catch (error) {
        return false;
      }
    },
  };
}



