/**
 * Dependency-free helpers for the LBH pipe-separated-value format.
 * Copy this file into any JavaScript project; it has no React/browser imports.
 *
 * Card: question|answer
 * Literal pipe in a card field: ||
 * Line break inside a field: ~~
 */
export const FIELD_SEPARATOR = "|";
export const INLINE_LINE_BREAK = "~~";
export const PROPERTIES_RECORD = "quiz.properties";

function asString(value) {
  return value == null ? "" : String(value);
}

export function encodeField(value) {
  return asString(value)
    .replace(/\|/g, "||")
    .replace(/\r\n|\r|\n/g, INLINE_LINE_BREAK);
}

export function decodeField(value) {
  return asString(value)
    .replace(/\|\|/g, FIELD_SEPARATOR)
    .replace(/~~/g, "\n");
}

function findFieldSeparator(line) {
  for (let index = 0; index < line.length; index += 1) {
    if (line[index] !== FIELD_SEPARATOR) continue;
    if (line[index + 1] === FIELD_SEPARATOR) {
      index += 1;
      continue;
    }
    return index;
  }
  return -1;
}

export function serializeCard(card) {
  if (!card || typeof card !== "object") {
    throw new TypeError("A card object is required");
  }
  return `${encodeField(card.question)}|${encodeField(card.answer)}`;
}

export function parseCard(line) {
  const text = asString(line);
  const separatorIndex = findFieldSeparator(text);
  if (separatorIndex < 0) {
    throw new Error("Invalid card record: missing field separator");
  }
  return {
    question: decodeField(text.slice(0, separatorIndex)),
    answer: decodeField(text.slice(separatorIndex + 1)),
  };
}

const PROPERTY_KEYS = ["name", "q_lang", "a_lang", "fontsize_q", "fontsize_a"];

function serializeProperty(key, value) {
  const text = asString(value);
  if (/\r|\n|\|/.test(text) || text.indexOf(INLINE_LINE_BREAK) >= 0) {
    throw new Error(`Quiz property "${key}" contains a reserved PSV character`);
  }
  return `${key}=${text}`;
}

export function serializeQuizProperties(properties) {
  if (!properties || typeof properties !== "object") {
    throw new TypeError("A quiz properties object is required");
  }
  const values = {
    name: properties.name,
    q_lang: properties.questionLanguage,
    a_lang: properties.answerLanguage,
    fontsize_q: properties.questionFontSize,
    fontsize_a: properties.answerFontSize,
  };
  return `${PROPERTIES_RECORD}|${PROPERTY_KEYS.map((key) =>
    serializeProperty(key, values[key])
  ).join(INLINE_LINE_BREAK)}`;
}

export function parseQuizProperties(line) {
  const prefix = `${PROPERTIES_RECORD}|`;
  const text = asString(line);
  if (text.indexOf(prefix) !== 0) throw new Error("Invalid quiz properties record");

  const raw = {};
  text.slice(prefix.length).split(INLINE_LINE_BREAK).forEach((part) => {
    const equalsIndex = part.indexOf("=");
    if (equalsIndex < 1) throw new Error(`Invalid quiz property: ${part}`);
    raw[part.slice(0, equalsIndex)] = part.slice(equalsIndex + 1);
  });
  return {
    name: raw.name || "",
    questionLanguage: raw.q_lang || "",
    answerLanguage: raw.a_lang || "",
    questionFontSize: raw.fontsize_q || "",
    answerFontSize: raw.fontsize_a || "",
  };
}

export function serializeDeck(deck, lineEnding = "\r\n") {
  if (!deck || typeof deck !== "object") throw new TypeError("A deck object is required");
  const lines = [];
  if (deck.properties) lines.push(serializeQuizProperties(deck.properties));
  (deck.cards || []).forEach((card) => lines.push(serializeCard(card)));
  return lines.join(lineEnding);
}

export function parseDeck(value) {
  const lines = asString(value).split(/\r\n|\r|\n/);
  if (lines.length && lines[lines.length - 1] === "") lines.pop();
  const deck = { properties: null, cards: [] };
  lines.forEach((line, index) => {
    if (line === "") return;
    try {
      if (line.indexOf(`${PROPERTIES_RECORD}|`) === 0) {
        if (deck.properties) throw new Error("Duplicate quiz properties record");
        deck.properties = parseQuizProperties(line);
      } else {
        deck.cards.push(parseCard(line));
      }
    } catch (error) {
      throw new Error(`Invalid PSV on line ${index + 1}: ${error.message}`);
    }
  });
  return deck;
}



