import React, { Component } from "react";
import counterpart from "counterpart";
import { serializeCard } from "../lib/psv";
import "./Forms.css";

class QuestionAnswer extends Component {
  state = { quizQuestion: "", quizAnswer: "", error: "" };

  add = () => {
    if (!this.state.quizQuestion.trim()) {
      this.setState({ error: counterpart.translate("questionRequired") });
      return;
    }
    this.props.buttonClicked(serializeCard({
      question: this.state.quizQuestion,
      answer: this.state.quizAnswer,
    }));
    this.setState({ quizQuestion: "", quizAnswer: "", error: "" });
    if (this.questionInput) this.questionInput.focus();
  };

  handleKeyDown = (event) => {
    if ((event.ctrlKey || event.metaKey) && event.key === "Enter") {
      event.preventDefault();
      this.add();
    }
  };

  render() {
    return (
      <div onKeyDown={this.handleKeyDown}>
        <div className="qa-grid">
          <label className="field textarea-field">
            <span>{counterpart.translate("question")}</span>
            <textarea ref={(input) => { this.questionInput = input; }}
              rows="8" placeholder={counterpart.translate("placeholderQ")}
              value={this.state.quizQuestion}
              onChange={(event) => this.setState({ quizQuestion: event.target.value, error: "" })} />
          </label>
          <label className="field textarea-field">
            <span>{counterpart.translate("answer")}</span>
            <textarea rows="8" placeholder={counterpart.translate("placeholderA")}
              value={this.state.quizAnswer}
              onChange={(event) => this.setState({ quizAnswer: event.target.value })} />
          </label>
        </div>
        {this.state.error && <p className="form-error" role="alert">{this.state.error}</p>}
        <div className="add-card-row">
          <span className="shortcut-hint">{counterpart.translate("shortcutHint")}</span>
          <button className="button button-primary add-card-button" onClick={this.add}>
            {counterpart.translate("addCard")}
          </button>
        </div>
      </div>
    );
  }
}

export default QuestionAnswer;



