import React, { Component } from "react";
import "./App.css";
import LangCombo, { initTranslations } from "./components/LangCombo";
import counterpart from "counterpart";
import Translate from "react-translate-component";
import QuizProps from "./fragments/QuizProps";
import QuestionAnswer from "./fragments/QuestionAnswer";
import { createJsonStorage } from "./lib/storage";

initTranslations();

const draftStorage = createJsonStorage(window.localStorage, "lbh-populator");
const DRAFT_KEY = "file-content";

class App extends Component {
  state = {
    fileContent: draftStorage.get(DRAFT_KEY, ""),
    copyStatus: "",
  };

  setFileContent = (fileContent) => {
    this.setState({ fileContent, copyStatus: "" });
    draftStorage.set(DRAFT_KEY, fileContent);
  };

  addLine = (line) => {
    this.setFileContent(`${line}\r\n${this.state.fileContent}`);
  };

  copyFileToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(this.state.fileContent);
      this.setState({ copyStatus: counterpart.translate("copied") });
    } catch (error) {
      this.setState({ copyStatus: counterpart.translate("copyFailed") });
    }
  };

  clearDraft = () => {
    if (window.confirm(counterpart.translate("clearConfirm"))) {
      this.setFileContent("");
    }
  };

  getCardCount = () => this.state.fileContent
    .split(/\r\n|\r|\n/)
    .filter((line) => line && line.indexOf("quiz.properties|") !== 0)
    .length;

  render() {
    const hasProperties = this.state.fileContent
      .split(/\r\n|\r|\n/)
      .some((line) => line.indexOf("quiz.properties|") === 0);

    return (
      <div className="app-shell">
        <header className="app-header">
          <div>
            <p className="eyebrow">LBH</p>
            <h1>{counterpart.translate("title")}</h1>
            <p className="subtitle">{counterpart.translate("subtitle")}</p>
          </div>
          <label className="language-picker">
            <span>{counterpart.translate("interfaceLanguage")}</span>
            <LangCombo onLangSet={() => this.forceUpdate()} />
          </label>
        </header>

        <main className="workspace">
          <section className="panel settings-panel">
            <details open={!hasProperties}>
              <summary>
                <span>
                  <strong>{counterpart.translate("quizProps")}</strong>
                  <small>{counterpart.translate("quizPropsHint")}</small>
                </span>
                <span className={hasProperties ? "status status-success" : "status"}>
                  {hasProperties
                    ? counterpart.translate("propertiesAdded")
                    : counterpart.translate("optional")}
                </span>
              </summary>
              <QuizProps buttonClicked={this.addLine} disabled={hasProperties} />
            </details>
          </section>

          <section className="panel entry-panel">
            <div className="section-heading">
              <div>
                <p className="step-label">{counterpart.translate("stepAddCard")}</p>
                <h2>{counterpart.translate("qa")}</h2>
              </div>
              <span className="card-count">
                {this.getCardCount()} {counterpart.translate("cards")}
              </span>
            </div>
            <QuestionAnswer buttonClicked={this.addLine} />
          </section>

          <section className="panel output-panel">
            <div className="section-heading output-heading">
              <div>
                <p className="step-label">{counterpart.translate("stepExport")}</p>
                <h2>{counterpart.translate("fileContent")}</h2>
                <p className="section-help">{counterpart.translate("autosaveHint")}</p>
              </div>
              <div className="output-actions">
                <button className="button button-secondary" onClick={this.clearDraft}
                  disabled={!this.state.fileContent}>
                  {counterpart.translate("clear")}
                </button>
                <button className="button button-primary" onClick={this.copyFileToClipboard}
                  disabled={!this.state.fileContent}>
                  {counterpart.translate("copyFileToClipboard")}
                </button>
              </div>
            </div>
            {this.state.copyStatus && (
              <p className="copy-status" role="status">{this.state.copyStatus}</p>
            )}
            <textarea
              id="filecontent"
              className="output-textarea"
              aria-label={counterpart.translate("fileContent")}
              placeholder={counterpart.translate("outputPlaceholder")}
              value={this.state.fileContent}
              onChange={(event) => this.setFileContent(event.target.value)}
              spellCheck="false"
            />
          </section>

          <details className="help-panel panel">
            <summary>{counterpart.translate("how2use")}</summary>
            <Translate content="instructions" component="div" unsafe={true} />
          </details>
        </main>
      </div>
    );
  }
}

export default App;



