import React, { Component } from "react";
import counterpart from "counterpart";
import {LANGS} from './langStructs.js'

import en from "../lang/en";
import ru from "../lang/ru";

export function initTranslations() {
    counterpart.registerTranslations("en-US", en);
    counterpart.registerTranslations("ru-RU", ru);
    counterpart.setLocale("en-US");
}

export function t(value) {
    return counterpart.translate(value)
}
// export function t(page,value) {
//     return counterpart.translate(`${page}.${value}`)
// }

/*

var langCode = "en-US"; // redux

- fetch from github and place into ls
- const transTree = ls[langCode] will return the entire tree
- const transFile = transTree[filename] will return the entire tree
- const value = transFile["title"]

*/

// forceUpdate has to be called on the App level to refresh the UI
// <LangCombo onLangSet={()=>this.forceUpdate()}/>
export default class LangCombo extends Component {
    state = {
    //   lang: "en",
    //   fileContent: "",
    };

    onLangChange = (e) => {
        // this.setState({ lang: e.target.value });


        counterpart.setLocale(e.target.value);
        this.forceUpdate()
        if(this.props.onLangSet) this.props.onLangSet();
      };

      render() {

        return (
            <select value={counterpart.getLocale()} onChange={this.onLangChange}>
              {/* <option value="en">English</option>
              <option value="ru">Russian</option> */}
              { LANGS.map( 
                    (item,idx) => ( <option key={idx} value={item.code}>{item.label}</option> ) 
                )}
            </select>
            )

        }

    }



